value:
          const filterQuery = true && $getGlobalModel('computed-for-chart-cities')
          const primaryData = filterQuery
            ? alasql(filterQuery, [$getGrid('cities')])
            : $getGrid('cities')

          return alasql(
	'SELECT `cities`.`name` AS `name1`, `cities`.`populationRename` \
	 FROM ? AS `cities` \
	',
	[primaryData]
)
